142: .loading-spinner { width: 20px; height: 20px; border: 2px solid var(--blue-200); border-top-color: var(--primary-main); border-radius: 50%; animation: spin 700ms linear infinite; }
143: .results-loading { min-height: 34px; display: flex; align-items: center; justify-content: center; gap: 8px; color: var(--text-secondary); background: var(--blue-50); border-bottom: 1px solid var(--blue-200); font-size: 12px; }
