 94:         @RequestParam(name = "q", required = false) String query,
 95:         @RequestParam(required = false) String status,
 96:         @RequestParam(required = false) String mediaType,
 97:         @RequestParam(required = false) String environment,
 98:         @RequestParam(required = false) String format,
 99:         @RequestParam(required = false) String region
100:     ) {
101:         validatePage(page, size);
102:         PageRequest pageRequest = PageRequest.of(page, size, parseSort(sort));
103:         return service.searchFrames(
104:             new FrameSearchCriteria(query, status, mediaType, environment, format, region),
105:             pageRequest
