127:         } catch (IllegalArgumentException exception) {
128:             throw new InvalidFrameRequestException("sort direction must be asc or desc");
129:         }
130: 
131:         Sort primary = Sort.by(direction, parts[0]);
132:         return "frameId".equals(parts[0]) ? primary : primary.and(Sort.by("frameId"));
