        return status;
    }

    public String getStatusReason() {
        return statusReason;
    }

    public LocalDateTime getCreatedDate() {
        return createdDate;
    }

    public LocalDateTime getModifiedDate() {
        return modifiedDate;
    }

    public LocationDetails getLocation() {
        return location;
    }

    public SiteDetails getSite() {
