  --magenta-1400: #812D5B;
  --magenta-1600: #561E3D;

  /* ----- Semantic roles ----- */
  --primary-light:    var(--blue-600);
  --primary-main:     var(--blue-1000);
  --primary-dark:     var(--blue-1400);
  --primary-contrast: var(--blue-50);

  --secondary-light:    var(--cyan-600);
  --secondary-main:     var(--cyan-1000);
  --secondary-dark:     var(--cyan-1400);
  --secondary-contrast: var(--cyan-50);

  --success-light:    var(--green-400);
  --success-main:     var(--green-600);
  --success-dark:     var(--green-800);
  --success-contrast: var(--green-50);

  --error-light:    var(--red-400);
  --error-main:     var(--red-600);
  --error-dark:     var(--red-800);
  --error-contrast: var(--red-50);

  --warning-light:    var(--orange-600);
  --warning-main:     var(--orange-1000);
  --warning-dark:     var(--orange-1400);
  --warning-contrast: var(--orange-50);

  --neutral-lighter: var(--gray-100);
  --neutral-light:   var(--gray-300);
  --neutral-base:    var(--gray-600);
  --neutral-dark:    var(--gray-800);

