  --fw-medium: 500;
  --fw-semibold: 600;

  /* Type scale (px at 16px root) */
  --fs-h1: 2rem;      /* 32px */
  --fs-h2: 1.5rem;    /* 24px */
  --fs-h3: 1.25rem;   /* 20px */
  --fs-h4: 1rem;      /* 16px */
  --fs-body1: 1rem;   /* 16px */
  --fs-body2: 0.875rem; /* 14px */
  --fs-label: 0.75rem;  /* 12px */
  --fs-caption: 0.75rem; /* 12px */
  --fs-table: 0.625rem;  /* 10px, uppercase */
  --fs-button: 0.875rem; /* 14px */

  --lh-h1: 2.5rem;
  --lh-h2: 2rem;
  --lh-h3: 1.5rem;
  --lh-h4: 1.5rem;
  --lh-body: 1.5rem;
  --lh-label: 1rem;

  /* ----- Spacing (factor Ã— 0.5rem = 8Ã—n px at 16px root) ----- */
  --sp-0:  0;
  --sp-1:  0.5rem;   /*  8px */
  --sp-2:  1rem;     /* 16px */
  --sp-3:  1.5rem;   /* 24px */
  --sp-4:  2rem;     /* 32px */
  --sp-5:  2.5rem;   /* 40px */
  --sp-6:  3rem;     /* 48px */
  --sp-7:  3.5rem;   /* 56px */
  --sp-8:  4rem;     /* 64px */
  --sp-10: 5rem;     /* 80px */

  /* ----- Shape ----- */
  --radius: 4px;
  --radius-lg: 8px;
  --radius-pill: 999px;

  /* ----- Elevation ----- */
  --elev-low:    0px 2px 4px -1px rgba(0, 34, 63, 0.15), 0px 1px 2px -1px rgba(0, 34, 63, 0.10);
  --elev-medium: 0px 4px 16px -2px rgba(0, 34, 63, 0.15), 0px 2px 4px -1px rgba(0, 34, 63, 0.15);
  --elev-high:   0px 8px 24px -2px rgba(0, 21, 38, 0.30), 0px 2px 16px -2px rgba(0, 34, 63, 0.20);

  /* ----- Breakpoints (for reference) ----- */
  --bp-xs: 0px;
  --bp-sm: 600px;
  --bp-md: 960px;
  --bp-lg: 1280px;
  --bp-xl: 1440px;
}

/* ============================================================================
   Base typography
   ============================================================================ */
html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
body {
  font-family: var(--font-sans);
  font-size: var(--fs-body2);
  color: var(--text-primary);
  background: var(--bg-default);
  margin: 0;
  line-height: var(--lh-body);
}
h1, .t-h1   { font: var(--fw-regular) var(--fs-h1)/var(--lh-h1) var(--font-sans); margin: 0; color: var(--text-primary); }
h2, .t-h2   { font: var(--fw-regular) var(--fs-h2)/var(--lh-h2) var(--font-sans); margin: 0; color: var(--text-primary); }
h3, .t-h3   { font: var(--fw-regular) var(--fs-h3)/var(--lh-h3) var(--font-sans); margin: 0; color: var(--text-primary); }
h4, .t-h4   { font: var(--fw-regular) var(--fs-h4)/var(--lh-h4) var(--font-sans); margin: 0; color: var(--text-primary); }
.t-h1b { font-weight: var(--fw-semibold); }
.t-h2b { font-weight: var(--fw-semibold); }
.t-h3b { font-weight: var(--fw-semibold); }
.t-h4b { font-weight: var(--fw-semibold); }
.t-body1  { font-size: var(--fs-body1); line-height: var(--lh-body); }
.t-body1b { font-size: var(--fs-body1); line-height: var(--lh-body); font-weight: var(--fw-semibold); }
.t-body2  { font-size: var(--fs-body2); line-height: var(--lh-body); }
.t-body2b { font-size: var(--fs-body2); line-height: var(--lh-body); font-weight: var(--fw-semibold); }
.t-body2m { font-size: var(--fs-body2); line-height: var(--lh-body); font-weight: var(--fw-medium); }
.t-label  { font-size: var(--fs-label); line-height: var(--lh-label); }
.t-labelb { font-size: var(--fs-label); line-height: var(--lh-label); font-weight: var(--fw-semibold); }
.t-caption{ font-size: var(--fs-caption); line-height: var(--lh-label); color: var(--text-secondary); }
